func (i brainIgnore) gitPathspecExclusions() []string {
	patterns := []string{"node_modules/**", "vendor/**", "dist/**", "build/**", "target/**", ".entire/**", ".git/**", ".env", "*.pem", "*.key"}
	for _, pattern := range i.patterns {
