		freshness := workspaceRepoFreshnessForRepo(cmd.Context(), opts, repo)
		result := workspaceQueryResult{RepoKey: repo.RepoKey, Name: repo.Name, Freshness: freshness}
		brainDir, err := brainDirForKey(opts.Env, repo.RepoKey)
		if err != nil {
			return err
		}
